-- Estructura de tabla para la tabla `turno_personal`
--

CREATE TABLE `turno_personal` (
  `id` int(11) NOT NULL,
  `turno_id` int(11) NOT NULL,
  `colaborador_id` int(11) NOT NULL,
  `funcion` varchar(60) NOT NULL,
  `ubicacion` varchar(60) DEFAULT NULL,
  `nave_id` int(11) DEFAULT NULL,
  `horario_colab` varchar(50) DEFAULT NULL,
  `estado` enum('activo','refrigerio','incidencia','traslado','permiso') NOT NULL DEFAULT 'activo',
  `radio` tinyint(1) NOT NULL DEFAULT 0,
  `foto_ingreso` varchar(255) DEFAULT NULL,
  `ingreso_lat` decimal(10,7) DEFAULT NULL,
  `ingreso_lng` decimal(10,7) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

