INSERT INTO `reconocimientos` (`id`, `colaborador_id`, `colaborador_nombre`, `colaborador_cargo`, `competencia`, `concepto`, `impacto`, `coordinador`, `coordinador_id`, `turno`, `fecha`, `zona_trabajo`, `detalle`, `estado`, `supervisor`, `supervisor_id`, `aprobado_at`, `foto_path`, `foto_drive_url`, `created_at`, `updated_at`) VALUES
(3, 15, 'HUANCA OLORTEGUI CAROLAY CELESTE', 'ASISTENTE DE ESTIBA', 'Iniciativa y compromiso', 'Propone ideas para mejorar formas de trabajo y tiene disposición para culminar sus tareas', NULL, 'ESCOBAR ROMERO LIZ MADELEINE', 5, 'dia', '2026-07-18', 'Muelle 4', 'Tally estaba embarcando bay 38 en bodega, faltaba 1 twin para pasar a cubierta, pero planning ya había mandado 3 dcv de 40 en cubierta sin notar que quedaba pendiente el twin. \n\nTally dio aviso oportunamente a planning y procedieron a enviar en twin faltante por la línea 5 de la QC105.', 'pendiente', NULL, NULL, NULL, 'uploads/reconocimientos/rec_foto_20260718_101545_250991a7.jpg', 'https://drive.google.com/file/d/125yQA2DCNeUH6hoBPK7AinveOxDJz0gS/view?usp=drivesdk', '2026-07-18 15:18:21', '2026-07-18 15:18:21'),
(4, 60, 'MUÑOZ PAREDES GLEN ALDAIR', 'ASISTENTE DE ESTIBA', 'Productividad', 'Mantiene un nivel de productividad por encima del promedio en las operaciones', NULL, 'SOTO MONTALVO YADIRA MILAGROS', 22, 'dia', '2026-07-26', 'Muelle 2', 'Realizó la mayor cantidad de despachos (60 vehículos) en comparación a sus compañeros', 'pendiente', NULL, NULL, NULL, 'uploads/reconocimientos/rec_foto_20260726_200249_22d1d16a.jpeg', 'https://drive.google.com/file/d/1HlFUXXnu87ik2kpY2nYOyqfxgqc4U2q9/view?usp=drivesdk', '2026-07-27 01:03:03', '2026-07-27 01:03:03'),
(5, 42, 'BARROSO OSORIO ANGIE SULU', 'ASISTENTE DE ESTIBA', 'Iniciativa y compromiso', 'Propone ideas para mejorar formas de trabajo y tiene disposición para culminar sus tareas', NULL, 'ESCOBAR ROMERO LIZ MADELEINE', 5, 'dia', '2026-07-27', 'Muelle 3', 'Estaba asignada a QC relevo, sin embargo reportó por iniciativa propia que una placa de minerales había sido pedeteada con 52 bbgs en BTOS. Se destaca que esté atenta a las operaciones en zop a pesar de no estar asignada a ese punto específico, le tomó screenshot desde su PDA y reportó en el momento a mi persona que pasó lo de la placa.', 'pendiente', NULL, NULL, NULL, NULL, NULL, '2026-07-28 02:15:25', '2026-07-28 02:15:25'),
(6, 25, 'CABANILLAS QUIÑONES LUIS FERNANDO', 'ASISTENTE DE ESTIBA', 'Adaptabilidad', 'Responde a traslados de posiciones de forma positiva', NULL, 'CONDOR FLORES JHENIFER', 18, 'dia', '2026-07-30', 'Muelle 3', 'Minuciosidad del Tally para identificar los vin\'s que no fueron encontrados en turno anterior , revisó uno por uno hasta lograr ubicarlos.\nPor otro lado , identificó bultos dentro de las maquinarias que no fueron pedeteados.', 'pendiente', NULL, NULL, NULL, NULL, NULL, '2026-07-31 00:51:18', '2026-07-31 00:51:18'),
(7, 74, 'MARTINEZ RAMOS RONALD MARCELO', 'ASISTENTE DE ESTIBA', 'Autonomía', 'Puede realizar tareas de forma independiente y da soporte a compañeros', NULL, 'CONDOR FLORES JHENIFER', 18, 'dia', '2026-07-30', 'Muelle 3', 'Encontró errores en zona de segregación y coordinó corrección', 'pendiente', NULL, NULL, NULL, NULL, NULL, '2026-07-31 00:52:37', '2026-07-31 00:52:37');
