(5, 63, 'RAMOS GARCIA JOSMERY GISELA', 'ASISTENTE DE ESTIBA', 'Muelle 4', 'Operaciones', '2026-07-18', 'ESCOBAR ROMERO LIZ MADELEINE', 5, '[{\"item\":\"Señalización\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Iluminación\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Orden y Limpieza\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Uso de Epps en la zona\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Ausencia de condiciones inseguras\",\"estado\":\"no_conforme\",\"observaciones\":\"La QC106 (línea 1) está trabajando con ITV en proa y popa (ambos sentidos). En la línea 1 esta posicionada las cajas del ST, provocando que los ITVS tengan dificultad para salir de la línea y permitir el pase del siguiente dcv\"},{\"item\":\"Proximidad de espacios de limpieza personal\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Proximidad de espacios de hidratación\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Condiciones ergonómicas\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Otros\",\"estado\":\"\",\"observaciones\":\"\"}]', 'Mover las cajas del ST al BR para que no obstaculicen la línea 1', 'Cuando tenemos embarque de ambos lados con ITV, se debe procurar que línea esté libre de obstáculos', '2026-07-18 16:25:58', '2026-07-18 16:25:58'),
(6, 56, 'OLORTEGUI ARELLAN NAYELI MEDALIT', 'ASISTENTE DE ESTIBA', 'Despacho de autos', 'Operaciones', '2026-07-19', 'ESCOBAR ROMERO LIZ MADELEINE', 5, '[{\"item\":\"Señalización\",\"estado\":\"no_conforme\",\"observaciones\":\"Ausencia de caseta para permanencia de tally\"},{\"item\":\"Iluminación\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Orden y Limpieza\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Uso de Epps en la zona\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Ausencia de condiciones inseguras\",\"estado\":\"no_conforme\",\"observaciones\":\"Ausencia de caseta en zona para permanencia de tally\"},{\"item\":\"Proximidad de espacios de limpieza personal\",\"estado\":\"no_conforme\",\"observaciones\":\"No se ubica lavadero o servicios cerca, el más próximo está en el edificio\"},{\"item\":\"Proximidad de espacios de hidratación\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Condiciones ergonómicas\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Otros\",\"estado\":\"\",\"observaciones\":\"\"}]', 'Colocar caseta en punto de despacho de cigüeñas para permanencia de tally', '', '2026-07-19 15:15:36', '2026-07-19 15:15:36'),
(7, 77, 'MUÑOZ CANALES JOMAIRA JAZMIN', 'ASISTENTE DE ESTIBA', 'Muelle 3', 'Operaciones', '2026-07-31', 'RISCO SEMINARIO GRECIA DEL MAR', 14, '[{\"item\":\"Señalización\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Iluminación\",\"estado\":\"no_conforme\",\"observaciones\":\"CASETAS NO SE ENCUENTRAN ILUMINADAS\"},{\"item\":\"Orden y Limpieza\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Uso de Epps en la zona\",\"estado\":\"conforme\",\"observaciones\":\"CUENTA CON LINTERNA ADICIONAL\"},{\"item\":\"Ausencia de condiciones inseguras\",\"estado\":\"conforme\",\"observaciones\":\"SE MANTIENE DENTRO DE CASETA, SE BRINDO ESCALERA PARA\"},{\"item\":\"Proximidad de espacios de limpieza personal\",\"estado\":\"no_conforme\",\"observaciones\":\"NO SE OBSERVA TACHOS DE DESPERDICIOS\"},{\"item\":\"Proximidad de espacios de hidratación\",\"estado\":\"conforme\",\"observaciones\":\"PUNTOS DE HIDRATACION CERCA\"},{\"item\":\"Condiciones ergonómicas\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Otros\",\"estado\":\"\",\"observaciones\":\"\"}]', '', '', '2026-08-01 04:30:56', '2026-08-01 04:30:56'),
(8, 79, 'REYES BELLO SHARON YOLANDA', 'ASISTENTE DE ESTIBA', 'Muelle 1', 'Operaciones', '2026-07-31', 'RISCO SEMINARIO GRECIA DEL MAR', 14, '[{\"item\":\"Señalización\",\"estado\":\"no_conforme\",\"observaciones\":\"NO HAY SEÑALIZACION PARA LOS DESPACHOS DE VEHICULOS\"},{\"item\":\"Iluminación\",\"estado\":\"no_conforme\",\"observaciones\":\"CASETA NO SE ENCUENTRA ILUMINADAS\"},{\"item\":\"Orden y Limpieza\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Uso de Epps en la zona\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Ausencia de condiciones inseguras\",\"estado\":\"no_conforme\",\"observaciones\":\"FALTA DE SEÑALIZACION\"},{\"item\":\"Proximidad de espacios de limpieza personal\",\"estado\":\"no_conforme\",\"observaciones\":\"\"},{\"item\":\"Proximidad de espacios de hidratación\",\"estado\":\"no_conforme\",\"observaciones\":\"\"},{\"item\":\"Condiciones ergonómicas\",\"estado\":\"conforme\",\"observaciones\":\"\"},{\"item\":\"Otros\",\"estado\":\"\",\"observaciones\":\"\"}]', '', '', '2026-08-01 04:32:48', '2026-08-01 04:32:48');
