INSERT INTO `sugerencias_tallyman` (`id`, `canal`, `colaborador_id`, `colaborador_nombre`, `colaborador_cargo`, `detalle`, `puntaje`, `puntaje_comentario`, `puntaje_por`, `puntaje_at`, `respuesta_whatsapp`, `respuesta_whatsapp_por`, `respuesta_whatsapp_at`, `respuesta_whatsapp_message_id`, `created_at`, `updated_at`) VALUES
(8, 'solicitud', 17, 'MENA VALDERRAMA GIANELA MILAGROS', 'ASISTENTE DE ESTIBA', 'Sería bueno que pasen la grabación de la capacitación de stuffing de minerales que hubo sobre el nuevo sistema para registrar los pesos ya que a varios de mis compañeros no les quedó claro incluyéndome, con esa grabación podremos verlo las veces que queremos y así poder practicar mas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-09 18:05:40', '2026-07-09 18:05:40'),
(9, 'propuesta', 17, 'MENA VALDERRAMA GIANELA MILAGROS', 'ASISTENTE DE ESTIBA', 'En las balanzas de gate aparece un mensaje el cual dice \"váyase\" luego que se levante la plumilla sería mejor que apareciera \"\"se puede retirar no olvidé su ticket \" ya que varios conductores nuevos se les olvida muy seguido y eso ocasiona demoras en las operaciones en patio', 4, 'Se puede poner un Letrero', 'TERRY PEREYRA EDGARD DAVID', '2026-07-10 14:31:40', NULL, NULL, NULL, NULL, '2026-07-09 18:09:31', '2026-07-10 14:31:40'),
(10, 'solicitud', 38, 'GIRON MORA DANUSKA MARIA', 'ASISTENTE DE ESTIBA', 'Buenas tardes estimados, habrá posiblidad de solicitar pizarras pequeñas  y plumones para la zona de Gate, cualquier información anticipada que se comenté, ej: de alguna placa en observación al ingreso o lista de planes, BL\'S de las unidades, tenerlo mapeado en esa pizarra ya sea durante el turno y el relevo, sería de gran ayuda para mayor visibilidad de los apuntes en zona.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-09 18:11:37', '2026-07-09 18:11:37'),
(11, 'propuesta', 57, 'AGUIRRE SALAZAR JUAN JOSE', 'ASISTENTE DE ESTIBA', 'Si se pudiera implementar para el área de desconsolidado de autos en los pedeteos de cada contenedor en la opción CFS del ITOS que los chasis que vayamos ingresando se puedan reflejar para poder evitar los  dobles pedeteos o chasis ingresado en un contenedor diferente que no sea el correcto.', 7, 'REVISAR BLOQUEO DE DOBLE PEDETEO PARA CHASIS', 'JHENIFER CONDOR', '2026-07-20 21:20:38', NULL, NULL, NULL, NULL, '2026-07-09 18:22:01', '2026-07-20 21:20:38'),
(12, 'propuesta', 47, 'LORA LEYVA NYLEEN MILENA', 'ASISTENTE DE ESTIBA', 'En el pre las líneas de ingreso tenemos zona bloqueadas considero que se podría poner como en la siguiente foto ya que en el día se puede manejar un orden y de noche en el tema de las devoluciones sería una buena opción y cada conductor sepa ya que si una unidad no tiene cita o la zona de box está cerrada pues ya no había necesidad de mandar a TD o que el conductor de atrás espere', 8, 'Derivar a Victor y a Alonso Soto', 'TERRY PEREYRA EDGARD DAVID', '2026-07-10 14:33:39', NULL, NULL, NULL, NULL, '2026-07-09 18:22:05', '2026-07-10 14:33:39'),
(14, 'solicitud', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', 'Se debería tomar en cuenta que los tallys que bajan de gate como en mi caso, se considere hacer sombra para los puestos, ya que hay varios procesos que se han ido actualizando y quede más claro para evitar cometer errores, Así como hay sombra para tallys de gate , se debe considerar también para zop.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-09 18:22:35', '2026-07-09 18:22:35'),
(15, 'solicitud', 47, 'LORA LEYVA NYLEEN MILENA', 'ASISTENTE DE ESTIBA', 'Poner un megáfono en balanza de salida e ingreso porque los conductores no escuchan a veces por su unidad pero ahí esos megáfonos Manuales para eso', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-09 18:23:07', '2026-07-09 18:23:07'),
(16, 'propuesta', 37, 'DULANTO ANGULO ANGELO MIJAIL', 'ASISTENTE DE ESTIBA', 'Sería bueno que en el Muelle 1, pongan una señalizacion de velocidad, ya que aveces los chóferes vienen en velocidad y respecto a ese detalle, en la PC13 mayormente pasan muy rapido los chóferes y en esa PC aveces no se logra ver bien la placa, cuando no se puede ver tenemos que salir de la PC por que justo esta detrás de la Hooper y hace que se cuadre mas adelante de nuestra visualización, con esa señalizacion creo yo, los chóferes qué suelen llegar en velocidad (qué no son todos) podria agilizarnos el pedeteo y no haya inconvenientes en el caso haya muchas tolvas.', 8, 'VIABLE (NO GARANTIZA SOLUCION DEL PROBEMA), ADICIONAL AGREGAR EL \"POR QUÉ\" QUE LOS CONDUCTORES SEPAN QUE ES PARA UNA BUENA TRANSMISION D DATOS', 'JHENIFER CONDOR', '2026-07-20 20:29:12', NULL, NULL, NULL, NULL, '2026-07-09 18:23:37', '2026-07-20 20:29:12'),
(17, 'observacion', NULL, NULL, NULL, 'Buenas tardes lo que he podido ver en el área de minerales es que los despachadores tienen mucha ingerencia en el trabajo del tally y muchas veces nos hacen perder nuestro orden de trabajo se debería dar una charla de orientación y limitaciones que puedan tener por que he visto que se hay unidades que salen sin nosotros controlarlo por que ellos los apuran es cello con respecto a los despachadores nuevos...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-09 18:24:14', '2026-07-09 18:24:14'),
(18, 'propuesta', 58, 'ALCALDE CASTAÑEDA CARLOS ENRIQUE', 'ASISTENTE DE ESTIBA', 'Adicionar un botón o alguna característica para identificar que contenedores quedan abiertos y cuáles quedan cerrados, en el tema del CFSS, para el nuevo programa de Balanza 2 (Minerales).', 1, 'YA SE ENCUENTRA LA OPCION EN EL SISTEMA', 'JHENIFER CONDOR', '2026-07-20 20:29:57', NULL, NULL, NULL, NULL, '2026-07-09 18:25:05', '2026-07-20 20:29:57'),
(19, 'solicitud', 30, 'DIAZ GONZALES MARIA FERNANDA', 'ASISTENTE DE ESTIBA', 'Buenas tardes, porfavor quisiera que todos podamos rotar en balanza 2, ya que algunos como en mi caso aun no hemos trabajado con el nuevo formato', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-09 18:25:16', '2026-07-09 18:25:16'),
(21, 'observacion', NULL, NULL, NULL, 'Yo creo que se debe considerar a todos los coordinadores para hacer las reuniones virtuales que hemos estado llevando para actualizaciones o procesos, quisiera escuchar también las explicaciones y opiniones de mis demás  coordinadoras y no solo escuchar a Evelyn.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-09 18:27:27', '2026-07-09 18:27:27'),
(22, 'propuesta', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', 'Considero que en el tema de desconsolidado, en el punto de trabajo el tally solo debe revisar daños y pedetear y el proceso de Tarja se haga en la ubicación donde se quedan los autos, ya que el personal de seguro encuentra daños que no se detectaron en el punto y hay que rehacer tarjas y genera doble trabajo.', 1, 'Actualmente se viene realizando asi', 'TERRY PEREYRA EDGARD DAVID', '2026-07-10 14:36:49', NULL, NULL, NULL, NULL, '2026-07-09 18:34:07', '2026-07-10 14:36:49'),
(23, 'propuesta', 26, 'CARRASCO PEREZ  LUIS MIGUEL', 'ASISTENTE DE ESTIBA', 'Ya que me encuentro en el CI especialmente en Gate (balanza) vi la deficiencia en cuestión a los conductores nuevos \r\nQue cuando ingresan tanto x recojo o embarque de un contenedor \r\nNo llegan a ubicarse con su zona de despacho \r\nX tal motivo sería bueno imprimir un plano de ubicación y pegarlas en las ticketeras de balanza ⚖️ cosa que el conductor llega a ese punto.retira su ticket y lo corrobora en el plano hacia donde tiene que llegar.', 8, 'Derivar con Victor y Alonso Soto', 'TERRY PEREYRA EDGARD DAVID', '2026-07-10 14:37:48', NULL, NULL, NULL, NULL, '2026-07-09 18:34:49', '2026-07-10 14:37:48'),
(24, 'observacion', NULL, NULL, NULL, 'Creo que los analistas deberían de bajar más seguido a zop cuando se necesita apoyo, creo que muchas veces, con un solo analista se abastece el gate ,y se necesita más apoyo en la zop.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-09 18:37:15', '2026-07-09 18:37:15'),
(25, 'propuesta', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', 'Al momento de iniciar operación en maíz , se debe considerar que se habilite las placas a trabajar de directa como interna para recién empezar la operación de cargar las tolvas , porque sucede que hacen lo contrario de que avance y carguen las tolvas cuando los tallys aún no tenemos todo habilitado para poder pedetear cada placa , que se sabe demora un poco , y a veces ya carga y va saliendo la tolva y no se puede pedetear y eso puede generar confusión y errores .\r\nEntonces creo primero para iniciar operación, se debe tener todo listo para que el tally pueda pedetear y ahí recién pasar las tolvas a cargar y no hacerlo al revés , ya que al inicio también las radios colapsan porque todos quieren hablar y no hay en ese momento la comunicación continúa.', 5, 'Se puede resolver rápido , pero se debe ajustar la comunicación con planning', 'TERRY PEREYRA EDGARD DAVID', '2026-07-10 14:41:48', NULL, NULL, NULL, NULL, '2026-07-09 18:43:41', '2026-07-10 14:41:48'),
(26, 'propuesta', 57, 'AGUIRRE SALAZAR JUAN JOSE', 'ASISTENTE DE ESTIBA', 'Haber si se podría implementar para GATE balanza salida se podría reflejar los dobles pedeteos en GATE-PASS. EJEMPLO: Acá en la ZOP, por decir una plataforma de BIGBAGS tiene que ir con 16 BIGBAGS y el compañero tally hizo un doble pedeteo y en sistema tiene 32(Solo se refleja en BTOS en la tarea de la placa)pero en físico solo 16 esa plataforma llega a CI balanza GATE salida el tally verifica en GATE-PASS la unidad que verifica en sistema sale 16(ahí solo refleja el primer pedeteo de 16 no el doble) y en físico también 16, el compañero(a) tally le da autorizado a la plataforma e ingresa a balanza y el tally verifica el ticket y sale 32 y bueno ahí el compañero(a) tally que confirmo la plataforma cometió un error porque el doble pedeteo no aparece reflejado en el GATE-PASS de ITOS, si ahí se podría implementar para que se pueda mostrar los dobles pedeteos para que así minimizar los errores en es punto también.', 8, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:37:56', NULL, NULL, NULL, NULL, '2026-07-09 18:46:51', '2026-07-20 20:37:56'),
(27, 'propuesta', 32, 'OLIVERA JORGE JOSE EDUARDO', 'ASISTENTE DE ESTIBA', 'En la balanza de gate( ingreso y salida) se deberia dar una limpieza a las cámaras que enfocan a las placas de las unidades y también a los escaner\'s para los faciales para mejorar y facilitar las lecturas, se podria dar cada 2 semanas el mantenimiento', 8, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:37:42', NULL, NULL, NULL, NULL, '2026-07-09 18:51:04', '2026-07-20 20:37:42'),
(28, 'propuesta', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', 'Si en caso se puede habilitar una opción  en el pda o haya una opción donde se pueda advertir un doble pedeteo , para así disminuir los errores , ojalá se pueda implementar para que el trabajo sea más fluido también', 8, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:37:28', NULL, NULL, NULL, NULL, '2026-07-09 18:54:17', '2026-07-20 20:37:28'),
(29, 'propuesta', 26, 'CARRASCO PEREZ  LUIS MIGUEL', 'ASISTENTE DE ESTIBA', '(Roro) al frente de balanza 2 se debería de hacer el pintado en el piso.\r\nNo tan distanciado como el de desconsolidado pero si almenos una línea recta que haga q los conductores puedan fijarse esa linea y los carros puedan quedar estaciónados en línea recta y no en curvas como suele suceder siempre así ganaríamos más espacio.ordenadamente', 8, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:37:19', NULL, NULL, NULL, NULL, '2026-07-09 19:46:41', '2026-07-20 20:37:19'),
(30, 'solicitud', 82, 'SALAS VEGA NOEMI DEL CARMEN', 'ASISTENTE DE ESTIBA', 'Solicito que se refuerce la comunicación con los clientes del área de minerales, a fin de evitar situaciones que afecten el control operativo.\r\nEl día 09 de julio, durante mi turno en el patio de minerales, uno de los clientes autorizó el ingreso de una plataforma para descarga sin previa coordinación conmigo ni el pedeteo correspondiente. Como consecuencia, una unidad llegó al gate sin registro, lo que generó una llamada a de declarar a mi persona y compañero de turno.\r\nPor ello, se solicita indicar a los clientes que no deben autorizar el ingreso ni descarga de plataformas sin la coordinación directa con el TALLYMAN de turno y sin cumplir con el proceso de pedeteo establecido.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-10 01:34:39', '2026-07-10 01:34:39'),
(31, 'propuesta', 82, 'SALAS VEGA NOEMI DEL CARMEN', 'ASISTENTE DE ESTIBA', 'En lo que son horarios, deseo proponer que los turnos sean por igual para el personal, ya que e tenido semanas con 3 días de turno, por ende se me a subido llamar para firmar que debo días, cuando otros compañeros suben a firmar días extras.\r\nOpino que los turnos deben ser por igual con todo el personal.', 8, 'REVISAR CON LABOR', 'JHENIFER CONDOR', '2026-07-20 20:39:36', NULL, NULL, NULL, NULL, '2026-07-10 01:37:03', '2026-07-20 20:39:36'),
(32, 'propuesta', 28, 'CONCEPCION OBREGON ALDO JESUS', 'ASISTENTE DE ESTIBA', 'En el pin station tanto como embarque y descarga colocar (Jersey de Cemento) para mayor seguridad tanto para el tallyman y opm, ya que el DCV aveces tiende a un poco salirse de su carril, afirmó esto ya que en la última vez que estuve en embarque me paso.', 8, 'REVISAR CON SHIFT Y VICTOR', 'JHENIFER CONDOR', '2026-07-20 20:39:10', NULL, NULL, NULL, NULL, '2026-07-10 12:52:41', '2026-07-20 20:39:10'),
(33, 'propuesta', 28, 'CONCEPCION OBREGON ALDO JESUS', 'ASISTENTE DE ESTIBA', 'Otra mejora que se podría ser pensando en la seguridad no sólo del tallyman sino tambien de nuestros compañeros opm, sería por cada carril colocar 2 casetas, y 1 opm por caseta así se evita que el opm camine de un lado a otro evitando así un riesgo de atropello por parte del DCV.', 8, 'REVISAR CON LOS SHIFT Y VICTOR', 'JHENIFER CONDOR', '2026-07-20 20:40:21', NULL, NULL, NULL, NULL, '2026-07-10 12:57:10', '2026-07-20 20:40:21'),
(35, 'propuesta', 46, 'CHANGANAQUI QUISPE SANDRA YANIRETT', 'ASISTENTE DE ESTIBA', 'Para desconsolidado , sería bueno que nos faciliten la lista de contenedores y chasis formato pdf ya en los PDA como en los roros  asi podemos rotular mas rápido los carros con el contenedor de el cual salio y no estamos en medio de el monta carga y el carro que se esta descargando , es un poco mas seguro y práctico.  Ya que cuando hay dos montacargas sacan de dos en dos los carros y se avanza mas rápido , se lo mencione a la coordinadora de turno,  pero  por si acaso lo escribo por aqui.  Porque ella estaba un poco ocupada y derrepente  se olvido ,sería buena opción', 10, 'VIABLE', 'JHENIFER CONDOR', '2026-07-20 20:40:49', NULL, NULL, NULL, NULL, '2026-07-10 20:53:02', '2026-07-20 20:40:49'),
(36, 'propuesta', 85, 'JOSE PABLO AUGUSTO PARDO RAMIREZ', 'Asistente de Estiba', 'Sistema-balanza minerales \r\nImplementar filtro para buscar unidades por cliente. Al momento de realizar el cuadre para cerrar los contenedores se necesita saber la cantidad de unidades de un cliente específico para cerrar ese Booking', 1, 'EL SISTEMA YA TIENE LA OPCION PARA EL FILTRADO', 'JHENIFER CONDOR', '2026-07-20 20:45:09', NULL, NULL, NULL, NULL, '2026-07-11 18:24:59', '2026-07-20 20:45:09'),
(37, 'propuesta', 85, 'JOSE PABLO AUGUSTO PARDO RAMIREZ', 'Asistente de Estiba', 'Sistema- balanza minerales. \r\nCorrección en botón de restar bultos, la operación se realiza con normalidad cuando se trata de descontar un bulto de un entero a un parcial, pero el proceso reverso (de parcial a entero) muestra un mensaje de error', 8, 'SE REVISA CON MONTERO', 'JHENIFER CONDOR', '2026-07-20 20:48:03', NULL, NULL, NULL, NULL, '2026-07-11 18:26:48', '2026-07-20 20:48:03'),
(38, 'propuesta', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', '-En los procesos de pedeteo para carga general , como el roro no se duplique un casillero más para poner el BL, ya que siempre aparece en la parte superior automáticamente, y lo veo repetitivo y quita tiempo estar escribiendo nuevamente, y nos pueda facilitar el trabajo.', 8, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:49:02', NULL, NULL, NULL, NULL, '2026-07-12 00:14:31', '2026-07-20 20:49:02'),
(39, 'propuesta', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', '-Que se implemente un sistema más completo y didáctico, como el de mineral, para la balanza de maíz, para tener un orden mejor y se guarde la info en una base de datos.', 10, 'REVISAR CON TERRY Y MONTERO', 'JHENIFER CONDOR', '2026-07-20 20:49:36', NULL, NULL, NULL, NULL, '2026-07-12 00:18:53', '2026-07-20 20:49:36'),
(40, 'observacion', NULL, NULL, NULL, 'Tema: Pre Gate\r\nUno de los problemas concurrentes ya informados incluso, es la generación de citas a conductores que no están registrados en identificación e incluso son conductores nuevos, llegando a balanza generando que pida tratamiento manual y tener que hacer retroceder la unidad, generando perdida de tiempo e incluso podría generar un accidente.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-12 22:29:37', '2026-07-12 22:29:37'),
(41, 'observacion', NULL, NULL, NULL, 'Tema: Gate pass de los tripulados de desconsolidado, en el pda solo figura el BL más no el chasis de la unidad para verificar con lo físico, pudiendo causar la salida de una unidad no correspondiente.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-12 22:31:10', '2026-07-12 22:31:10'),
(42, 'observacion', NULL, NULL, NULL, 'Tema: Gate pass de los tripulados de desconsolidado, en el pda solo figura el BL más no el chasis de la unidad para verificar con lo físico, pudiendo causar la salida de una unidad no correspondiente. Lourdes.R', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-12 22:31:42', '2026-07-12 22:31:42'),
(43, 'propuesta', 14, 'RUCANA TINEO LOURDES REGINA', 'ANALISTA DE TROUBLE DESK', 'Tema: Gate pass de los tripulados de desconsolidado, en el pda solo figura el BL más no el chasis de la unidad para verificar con lo físico, pudiendo causar la salida de una unidad no correspondiente. Lourdes.R\r\n\r\nComo propuesta de mejora: \r\nEn el pedea debe figurar el chasi correspondiente al físico para que así pueda validar el tally de balanza y evitar errores.', 10, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:50:28', NULL, NULL, NULL, NULL, '2026-07-12 22:33:51', '2026-07-20 20:50:28'),
(44, 'observacion', NULL, NULL, NULL, 'Tema: Pre Gate\r\nSe le genera citas a unidades no registradas y a conductores nuevos o sin registro previo, algo que ya ha sido informado en varias ocasiones.\r\nEso hace que al ingresar a balanza esta pida tratamiento manual, se tiene que hacer retroceder la unidad, generando retraso y peor aún puede generar algún accidente.\r\n\r\nPropuesta de mejora: \r\nAl área de comercial específicamente a citas o en la plataforma, debería saltar una alerta con esas unidades no registradas, conductores nuevos o con documentos por regularizar, así antes de generar las citas los coordinadores ponen en regla toda documentación y hacemos que el ingreso sea fluido y a la vez correcto.\r\nLourdes R', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-12 22:38:54', '2026-07-12 22:38:54'),
(45, 'propuesta', 65, 'TORRES RICHARTE JOSE EDUARDO', 'ASISTENTE DE ESTIBA', 'Algo que se a visto últimamente en el desconsolidado de autos , es que los compañeros OPM se olvidan de sacar las fajas que van enganchada en la parte de abajo del carro. Entonces lo que sucede es cuando vienen los choferes por sus propios medios a llevarse los vehículos , se quedan enganchado por que la faja pisa la llanta y el carro se traba al avanzar y eso puede dañar el vehículo. Ahí como referencia en esta nueva aplicación mando una foto referencial.', 10, 'REVISAR PROCEDIMIENTO', 'JHENIFER CONDOR', '2026-07-20 20:51:29', NULL, NULL, NULL, NULL, '2026-07-13 05:24:49', '2026-07-20 20:51:29'),
(46, 'solicitud', 65, 'TORRES RICHARTE JOSE EDUARDO', 'ASISTENTE DE ESTIBA', 'Hay una problemática que tienen los choferes externos para despacho dimensionado en cama baja. Lo que sucede es que el equipo de HSE hace que todos los conductores esperen y salen en grupo grande de 8 hasta 10 carretas por el eje 3 y lo que pasa es que van pegados a su almacén y en el camino ellos hacen trafico obstruyendo el carril y vehículos menores no pueden adelantar porque van pegados por la carretera , también cuando llegan a su almacén a dejar la carga como llegan todos juntos se congestiona y solo pueden ir descargando de 2 en 2 y pierden tiempo. Entonces su mejora para ellos es que los despachen de 3 en 3 para que ellos puedan ir avanzando y así ganar tiempo y puedan darse otra vuelta al puerto porque pierden tiempo esperando a que otras cama baja trinquen , mientras que ellos podrían ir saliendo y así no hubiera cuellos de botella en la carretera.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-13 05:47:57', '2026-07-13 05:47:57'),
(47, 'propuesta', 63, 'RAMOS GARCIA JOSMERY GISELA', 'ASISTENTE DE ESTIBA', 'En el caso de balanza quisiera proponer que se puede agregar una opción de quitar bultos y no solo peso en la misma transacción ya que ahora también eh visto esa manera de mover un bulto de entero a parcial en la misma placa', 1, 'YA EXISTE LA OPCION', 'JHENIFER CONDOR', '2026-07-20 20:51:57', NULL, NULL, NULL, NULL, '2026-07-13 11:47:27', '2026-07-20 20:51:57'),
(48, 'propuesta', 63, 'RAMOS GARCIA JOSMERY GISELA', 'ASISTENTE DE ESTIBA', 'En el caso de balanza quisiera proponer que se puede agregar una opción de quitar bultos y no solo peso en la misma transacción ya que ahora también eh visto esa manera de mover un bulto de entero a parcial en la misma placa', 1, 'YA EXISTE LA OPCION', 'JHENIFER CONDOR', '2026-07-20 20:52:16', NULL, NULL, NULL, NULL, '2026-07-13 11:47:35', '2026-07-20 20:52:16'),
(49, 'propuesta', 63, 'RAMOS GARCIA JOSMERY GISELA', 'ASISTENTE DE ESTIBA', 'También con el tema de balanza se que es bueno el nuevo implemento del sistema pero también no estaría mal refrescar de vez en cuando el metodo pasado porque un caso hipotetico pase algo con la computadora necesitarás actuar al momento y sacar manualmente pero si no sabes el método como se haría necesitarías sacar a otro compañero de otro punto por apoyo', 8, 'CAPACITACION', 'JHENIFER CONDOR', '2026-07-20 20:54:07', NULL, NULL, NULL, NULL, '2026-07-13 12:32:02', '2026-07-20 20:54:07'),
(50, 'propuesta', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', 'En gate, al generar la cita, el sistema bloquee y no acepte crear doble cita , ya que hay casos que vienen con doble cita de entrega y retiro al mismo tiempo en contenedor , o para la carga general que se duplica el peso  y así evitar que vengan las unidades así al pregate.', 10, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:54:22', NULL, NULL, NULL, NULL, '2026-07-13 12:45:52', '2026-07-20 20:54:22'),
(51, 'propuesta', 65, 'TORRES RICHARTE JOSE EDUARDO', 'ASISTENTE DE ESTIBA', 'Una problemática que se ve en la balanza 2 últimamente es que solo tenemos una computadora para el registro de pesos de minerales , repesajes de contenedores con itv ,  pesaje de unidades de sunat o externos como furgones para avituallamiento , registro de cierre de contenedores, etc. Una sola PC no basta para toda la implementación que está habiendo en el puerto , lo recomendado por todos los compañeros es que se coloque dos pantallas enlazadas como tienen los analistas en el trouble desk eso ayudaría a que la información se pueda subir al sistema en simultáneo y a la vez mejorar la capacidad de memoria ram y GB para una mejor velocidad en el sistema.', 2, 'POR EL MOMENTO LA OPERACION ES MANEJABLE CON UNA Y NO COMPENSA LA INVERSION ECONOMICA', 'JHENIFER CONDOR', '2026-07-20 20:56:10', NULL, NULL, NULL, NULL, '2026-07-13 22:31:05', '2026-07-20 20:56:10'),
(52, 'propuesta', 67, 'VASQUEZ MORA SHAUNNY MILAGROS', 'ASISTENTE DE ESTIBA', 'Para el Gate - Balanza.\r\n Seria bueno que se pueda sincronizar la balanza con los semaforos, ya que cuando una unidad ingresa a la balanza el semaforo sigue estando en verde, cuando debe pasar a rojo. Hay casos que no lee su facil o su huella y el analista indica que tiene que cambiar de linea la unidad. Pero como el semaforo sigue en verde otra unidad se coloca detras (en cola) y no va permitir que pueda retroceder. Y no va permitir fluir y se tendria una linea menos en caso dicha unidad no pueda avanzar ni retroceder.', 10, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:56:50', NULL, NULL, NULL, NULL, '2026-07-13 22:36:48', '2026-07-20 20:56:50'),
(53, 'propuesta', 67, 'VASQUEZ MORA SHAUNNY MILAGROS', 'ASISTENTE DE ESTIBA', 'Para el Gate - Balanza.\r\n Seria bueno que se pueda sincronizar la balanza con los semaforos, ya que cuando una unidad ingresa a la balanza el semaforo sigue estando en verde, cuando debe pasar a rojo. Hay casos que no lee su facil o su huella y el analista indica que tiene que cambiar de linea la unidad. Pero como el semaforo sigue en verde otra unidad se coloca detras (en cola) y no va permitir que pueda retroceder. Y no va permitir fluir y se tendria una linea menos en caso dicha unidad no pueda avanzar ni retroceder.', 10, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 20:57:03', NULL, NULL, NULL, NULL, '2026-07-13 22:38:22', '2026-07-20 20:57:03'),
(54, 'observacion', NULL, NULL, NULL, 'Creo que debería de estar un analista en los  procesos de balanza como mineral o repesajes porque se maneja el sistema y ellos ya tienen mayor conocimiento en ello, al estar en ese puesto fijo pueden rotar en el gate , ya que con un solo analista en gate, se puede trabajar conjunto al supervisor.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-14 16:10:28', '2026-07-14 16:10:28'),
(55, 'propuesta', 23, 'VEGA DURAND VERENICE SARAI', 'ASISTENTE DE ESTIBA', 'BALANZA 2. MINERALES\r\nAñadir en el nuevo sistema de minerales el despliegue de los contenedores asignados que van a ser cerrados ( el mismo día) o de los que faltan cerrar ( pendiente de días anteriores) \r\nConsiderando: NUMERO DE CONTENEDOR, TARA Y PLAYLOAD.\r\n\r\nPara reducir los errores de digitación.', 8, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 21:17:46', NULL, NULL, NULL, NULL, '2026-07-14 19:20:48', '2026-07-20 21:17:46'),
(56, 'observacion', NULL, NULL, NULL, 'Buenas tardes \r\nLa señorita que brindan la comida en la Zop ya son varias veces que no hace caso cuando uno le pide que sirva poco arroz , haciendo que la comida sea desperdiciada y arrojada a los contenedores de basura. Mientras esa comida le pueden servir más otros compañeros. Sería bueno mejorar en ese tema porque votar la comida no me parece nada bueno.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-15 17:47:52', '2026-07-15 17:47:52'),
(57, 'propuesta', 65, 'TORRES RICHARTE JOSE EDUARDO', 'ASISTENTE DE ESTIBA', 'Una mejora para los operadores de hopper , es que ellos no tienen visión a la hora de cargar las tolvas se le dificulta para el llenado lado mar , porque no tienen mucha visualización del lugar donde se encuentra. Una mejora sería sacar las dos rendijas en forma de triángulo que tienen adelante de ellos para que así eviten los derrames del producto que están cargando. O ponerle pantalla con cámaras para que no tenga puntos ciegos y la producción fluya eso pasa más en lo que es soya y urea ya que el producto como no tiene mucho peso y es más volumen , las tolvas tienen que ir cargadas al tope y en esas circunstancia pasa que derraman por no poder visualizar el otro extremo de la tolva.', 10, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 21:17:18', NULL, NULL, NULL, NULL, '2026-07-15 17:55:26', '2026-07-20 21:17:18'),
(58, 'observacion', NULL, NULL, NULL, 'Buenas tardes, \r\nSobre atención y manejo de porciones en el comedor.\r\n\r\nPor medio de la presente quiero expresar mi malestar respecto al servicio del comedor.\r\n\r\nActitud del personal: Varios trabajadores atienden de forma déspota y con malas actitudes. No saludan, responden de mala gana y no hay un trato respetuoso hacia los trabajadores solamente cuando ven que son supervisores o jefes cambian de actitud y son amables.\r\n\r\nDesperdicio de alimentos: Al momento de servir el arroz, el personal indica \"avísenme si desean bastante o poco\". Sin embargo, al final a todos nos sirven una porción excesiva sin importar lo que pedimos. Esto genera que mucha comida se quede en el plato y termine en la basura, siendo un desperdicio.\r\n\r\nSolicito que se capacite al personal en buen trato al usuario y que se respete realmente la cantidad de arroz (entre otro) que cada uno pide, para evitar el desperdicio de comida y de recursos.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-15 18:17:56', '2026-07-15 18:17:56'),
(59, 'solicitud', 67, 'VASQUEZ MORA SHAUNNY MILAGROS', 'ASISTENTE DE ESTIBA', 'Buenas noches;\r\nSobre la charla de lecciones aprendidas, considero que seria bueno que todos mis compañeros participen en un solo grupo. Así todos podrian brindar sus ideas, comentarios y aportes de todas las áreas. Por lo tanto, todo el Team de Tallyman nos informariamos y podrian seguir una sola línea, atacando en los errores que se detectan en el puerto  para seguir mejorando y tener una comunicación mas clara.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-16 04:25:58', '2026-07-16 04:25:58'),
(60, 'propuesta', 82, 'SALAS VEGA NOEMI DEL CARMEN', 'ASISTENTE DE ESTIBA', 'Quisiera proponer una mejora en la operación del Pin Station de descarga respecto al posicionamiento de los DCV.\r\nActualmente, los DCV se estacionan justo a la altura de la caseta, lo que genera una dificultad cuando se atienden unidades tipo twin. En estos casos, no es posible colocar la escalera de manera adecuada para realizar el pedeteo del precinto y la verificación de la serie en la parte central del DCV.\r\nDebido a ello, hay veces en la que me veo obligada a realizar maniobras no seguras, como subir a la caseta para poder acceder al centro del DCV, lo cual representa un riesgo operativo, aunque se haga con el fin de no detener la operación.\r\nEn ese sentido, propongo que se evalúe la posibilidad de coordinar con Jutopilot para que el DCV pueda estacionarse aproximadamente un metro antes de la caseta. \r\nEsto permitiría el uso correcto de la escalera y una ejecución más segura del proceso.', 10, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 21:16:22', NULL, NULL, NULL, NULL, '2026-07-17 16:16:38', '2026-07-20 21:16:22'),
(61, 'propuesta', 53, 'DAVILA CESPEDES YANIRA MAYRA', 'ASISTENTE DE ESTIBA', 'Buen día. \r\nPor medio del presente, hago llegar la propuesta de mejora para el proceso de descarga de graneleros, elaborada a partir de la experiencia operativa como Asistente de Estiba.\r\n\r\nLa propuesta consiste en implementar un filtro automático en el sistema que permita validar el producto y las placas de las tolvas por escotilla, de acuerdo con el plan de citas, con el objetivo de minimizar equivocaciones en la descarga del producto, evitar el despacho a tolvas incorrectas y fortalecer el control y la trazabilidad de la operación.\r\n\r\nAgradeceré puedan revisar la propuesta adjunta y quedo atenta a cualquier comentario o sugerencia que contribuya a su evaluación.\r\n\r\nSaludos cordiales,\r\n\r\nYanira Dávila Céspedes\r\nAsistente de Estiba', 10, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 21:15:03', NULL, NULL, NULL, NULL, '2026-07-17 16:30:08', '2026-07-20 21:15:03'),
(62, 'propuesta', 53, 'DAVILA CESPEDES YANIRA MAYRA', 'ASISTENTE DE ESTIBA', 'Asunto: Propuesta de Ficha Operativa – Buque ECO MARIN\r\n\r\nBuen día. \r\nAdjunto la Ficha Operativa del buque ECO MARIN, elaborada con el propósito de contar con una guía visual de consulta rápida que permita conocer las características y particularidades del buque antes del inicio de las operaciones.\r\n\r\nEsta información busca facilitar la planificación del embarque de contenedores, optimizar los tiempos de operación y contribuir a una ejecución más segura y eficiente.\r\n\r\n\r\nYanira Dávila Céspedes\r\nAsistente de Estiba', 10, 'DERIVAR', 'JHENIFER CONDOR', '2026-07-20 21:08:37', NULL, NULL, NULL, NULL, '2026-07-17 16:34:08', '2026-07-20 21:08:37'),
(63, 'observacion', NULL, NULL, NULL, 'Buens tardes , el dia de ayer la ultima amanecida turno noche ! Se trabajo la nave de maiz Golabl Coral Muelle 1. Resulta que LLEGO UNA TOLVA DE MAIZ SIN PEDETEAR Y SIN FIRMA AL GATE CI SALIDA.\r\n\r\nDe analista estaba Vanessa y se comunico con la coordinadora Jennifer para que la tally pueda detear la tolva y pueda recien salir .\r\nLa placa era BFZ833\r\n\r\nReporto esto para que se investigue y se reporte  ese error. Y se mejore en ese tema', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-17 19:37:46', '2026-07-17 19:37:46'),
(64, 'propuesta', 30, 'DIAZ GONZALES MARIA FERNANDA', 'ASISTENTE DE ESTIBA', 'Quisiera se pueda evaluar la implementacion de uno o dos mapas plastificados en la balanza del gate para poder dirigir a los conductores nuevos hacia la zona donde deben de retirar o dejar los contenedores, en el mapa debe de figurar la salida del tunel donde se pueda visualizar zonas de la zop como son la rotonda, la zona de desconexion de los reffers y los bloques C, B y A ha modo de croquis para que a los conductores nuevos se les haga mas facil el ingreso y nosotros poder explicarles de una manera mas sencilla y didactica', 10, 'VIABLE', 'JHENIFER CONDOR', '2026-07-20 21:07:20', NULL, NULL, NULL, NULL, '2026-07-18 05:55:59', '2026-07-20 21:07:20'),
(65, 'solicitud', 30, 'DIAZ GONZALES MARIA FERNANDA', 'ASISTENTE DE ESTIBA', 'He notado que las sillas tanto de pre gate como de balanza del gate se encuentran rotas, perjudicando la salud de todos los que rotamos en esas zonas, seria bueno el cambio de estas no solo para comodidad sino tambien por salud fisica de todos nosotros.\r\nMaria Fernanda Diaz Gonzales', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-18 05:57:49', '2026-07-18 05:57:49'),
(66, 'propuesta', 30, 'DIAZ GONZALES MARIA FERNANDA', 'ASISTENTE DE ESTIBA', 'Se envia la foto del croquis para que pueda ser sacado en grande y poder explicarles con mayor facilidad a los conductores nuevas en balanza del gate, ya que la foto al estar en el pda se ve muy chica', 10, 'VIABLE, REVISAR PLANO', 'JHENIFER CONDOR', '2026-07-20 21:06:41', NULL, NULL, NULL, NULL, '2026-07-18 11:58:56', '2026-07-20 21:06:41'),
(67, 'propuesta', 28, 'CONCEPCION OBREGON ALDO JESUS', 'ASISTENTE DE ESTIBA', 'Cuando se está en el muelle 1 o 2 en un barco de maiz o soya y haya tolvas internas y van a los almacenes el tally de grúa, suele avisar al tally de balanza de que escotilla salio la tolva para darle la verificación pero pasa que en ese canal están los compañeros opms, supervisor entre otros y justo hablan cuando el tallys está queriendo dar la verificación y la radio suelen cruzarse, se corta o no escucha lo que uno quiere decir, entonces propongo que haya 2 canales uno general donde estan todos y otro canal solo para los tallys que están en la grúa y balanza solo nosotros para así evitar ese conflicto con la radio oh que se cruze o no se escuche, así he visto que lo manejan los opms cuando están en un barco containero teniendo su propio canal interno aparte del canal general donde están todos', 8, 'REVISAR CON VICTOR Y LOS SHIFT', 'JHENIFER CONDOR', '2026-07-20 21:02:51', NULL, NULL, NULL, NULL, '2026-07-18 18:00:13', '2026-07-20 21:02:51'),
(68, 'propuesta', 28, 'CONCEPCION OBREGON ALDO JESUS', 'ASISTENTE DE ESTIBA', 'Cuando toque trabajar en el muelle 3 o 4 con barco containero sería bueno que se pueda implementar al PDA el plano ya que aveces en papel es un poco tedioso estar con todas las hojas y estar marcando con el lapicero, también ocurre que luego cuando el relevo llega ya no tienen los planos o se llega a relevar sin ello y es complicado estar sin plano cuando llegan los simples o twines para poder ver la estructura del barco, algo automatizado seria poder tener el plano en el PDA y marcar a la vez los CTN que van pasando con una actualización de tiempo real, para poder también nosotros llevar el control de cuantos CTN faltan por terminar el BAY', 5, 'PLANO EN PDF VIABLE, OPCION DE MARCAR AVANCE REVISAR', 'JHENIFER CONDOR', '2026-07-20 21:01:04', NULL, NULL, NULL, NULL, '2026-07-20 00:37:42', '2026-07-20 21:01:04'),
(69, 'solicitud', 28, 'CONCEPCION OBREGON ALDO JESUS', 'ASISTENTE DE ESTIBA', 'Quisiera que se pueda hacer una charla sobre los pasos detallados que se deben escribir en el EIR en el depot, consultando al Supervisor directo, lo comento porque hay algunos tallys que en el EIR colocan alguna información y otros tallys no, sería bueno que todos tengamos claro para no evadir información como es en donde dice Cliente: algunos lo colocan otros no, otro punto en la Hora: cuando entra el turno de noche pasando las 00:00 algunos colocan la fecha de la noche y otros la fecha del día siguiente', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-20 01:02:55', '2026-07-20 01:02:55'),
(70, 'observacion', NULL, NULL, NULL, 'Quisiera solicitar que las coordinadoras apliquen un mejor criterio al momento de evaluar si corresponde o no una declaración. Esta situación está generando en varios compañeros un nivel importante de estrés, ya que en muchas ocasiones necesitamos salir a tomar nuestro refrigerio o atender otras necesidades básicas.\r\n\r\nEn particular, respecto al tema del refrigerio, considero que los retrasos ocasionados por factores ajenos a nuestra responsabilidad no deberían ser imputados a los tallys. Por ejemplo, cuando el bus demora en llegar, nos hace esperar o simplemente no se encuentra en el punto de recojo, no resulta justo que se nos responsabilice por esos minutos de retraso.\r\n\r\nEste tipo de situaciones no afecta la operación ni perjudica a los compañeros que esperan el relevo; sin embargo, terminamos siendo observados por circunstancias que escapan de nuestro control.\r\n\r\nPor ello, solicito que exista una mayor comprensión y un criterio más objetivo al momento de evaluar estos casos. En todo caso, si el retraso se debe al servicio de transporte, la responsabilidad debería recaer en quien corresponda, y no directamente en los tallys, como viene ocurriendo actualmente. Considero que las coordinadoras, como parte de nuestro equipo de soporte, deberían ayudarnos a encontrar una solución justa y no generar observaciones por hechos que no dependen de nosotros.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-20 11:44:39', '2026-07-20 11:44:39'),
(71, 'propuesta', 20, 'MELGAREJO FALCON RUTH ISABEL', 'ASISTENTE DE ESTIBA', 'Sería bueno hacer folletos o volantes para los conductores que se dirigen a hacer el recojo del contenedor a zop\r\nYa que en reiteradas veces la mayoría se termina perdiendo en zop ya que algunos no tiene una noción de como es allá abajo\r\nPor más inducción que reciban \r\nAlgunos son nuevos y no lo tienen tan claro \r\nTambién sería bueno hacer un mantenimiento a las balanzas de GATE ya que también en reiteradas veces no jala el peso o no lee bien las placas y por ello las unidades tiene que retroceder y volver a ingresar y eso es un poco inseguro y también retrasa la operación ya que cuando hay mucha operativad es un poco complicado....', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-22 23:58:16', '2026-07-22 23:58:16'),
(72, 'propuesta', 17, 'MENA VALDERRAMA GIANELA MILAGROS', 'ASISTENTE DE ESTIBA', 'En el gate en citos en la opción de gate in cuando entran refers de conexión llenos es muy importante poner la foto del Booking,puerta del contenedor, precintos y ahora incluimos captura de pantalla del pedeteo donde se visualiza la temperatura y precintos ya que eso nos respalda como prueba de nuestro pedeteo muy bien hecho. El problema es el tema de la cantidad de fotos no es posible poner las 6 fotos correspondientes ya que solo alcanza para poner 4 y muchas veces los precintos están separados y vienen 3 en la mayoría de ocasiones. Propongo que incluyan 6 espacios para poner fotos hacia haría más eficiente nuestro trabajo.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-23 13:11:24', '2026-07-23 13:11:24'),
(73, 'propuesta', 76, 'MELGAREJO AQUINO MILAGROS JUDITH', 'ASISTENTE DE ESTIBA', 'Buenos días:\r\n\r\nAdjunto propuesta de mejora, en base a lo que se busca del instructivo de los procesos que realizamos en operaciones. Este adjunto corresponde al despacho de carga fraccionada y project cargo. Cabe resaltar que, en las imágenes solo proyecta un referente al sistema, cuando obtenga las imágenes serán reemplazadas como corresponde.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-24 15:17:13', '2026-07-24 15:17:13'),
(74, 'propuesta', 28, 'CONCEPCION OBREGON ALDO JESUS', 'ASISTENTE DE ESTIBA', 'Hoy me toco en muelle 2 con el barco de cemento, y vi algo que creo que no deberia pasar, hay momentos en que una persona quiere contactar al supervisor encargado o hacerle una pregunta y aveces no se llega a contactarlo a tiempo, ya que al estar todos en un solo canal se satura y no se llega a escuchar nada, mi propuesta sería que se designe la radio con canales distintos para cada trabajo que se va a realizar ya sea OPM, TALLYS, STAKER, MONTACARGAS, etc, asi se evitara esa saturacion y el tiempo prolongado de respuesta alguna ya sea del supervisor u otro personal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-27 14:21:38', '2026-07-27 14:21:38'),
(75, 'propuesta', 82, 'SALAS VEGA NOEMI DEL CARMEN', 'ASISTENTE DE ESTIBA', 'Propuesta de Mejora – Zona Patio Minerales\r\n\r\nEn la jornada de ayer 27.07.2026 se evidenció una alta afluencia de vehículos en la zona de patio minerales, lo cual generó desorden en el flujo operativo, principalmente por la intervención no coordinada del personal desde las designaciones a los puntos de trabajo en dicha zona y la falta de control en el ingreso, registro y pedeteo de unidades.\r\n1. Problemática identificada:\r\nSe observó que algunos despachadores, debido a la premura por agilizar la salida de unidades, toman la iniciativa de dirigir a los conductores sin contar con la confirmación previa del tallyman respecto al registro de las unidades. Esta práctica genera desorden, riesgo de errores en el registro, placas pueden llegar a gate sin ser pedeteada.\r\nAsimismo, pese a la implementación de Jersey Bar en la zona, se evidenció falta de señalización adecuada. Durante el inicio de la operación, se produjo el ingreso simultáneo de aproximadamente 30 unidades, lo cual generó congestión, redujo la visibilidad y limitó el espacio operativo.\r\n2. Propuesta de mejora:\r\nImplementar  la presencia de un OPM en la zona de patio minerales, con la función específica de:\r\nSegregar las unidades según indicación del tallyman.\r\nControlar el orden de ingreso de los vehículos a las plataformas.\r\nGarantizar que cada unidad sea previamente registrada, verificada y autorizada antes de su desplazamiento.\r\nReforzar la señalización en la zona, incorporando letreros visibles que regulen el flujo vehicular, especialmente en el arranque de operaciones, evitando el ingreso masivo y desordenado de unidades.\r\n3. Beneficios esperados:\r\nMejora en el orden y control del flujo vehicular.\r\nReducción de errores en el registro de unidades.\r\nMayor seguridad operativa.\r\nOptimización de tiempos sin afectar la trazabilidad del proceso.\r\nSe solicita tener en cuenta  la evaluación e implementación de estas medidas a fin de fortalecer la eficiencia y control en las operaciones del patio de minerales', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-28 17:50:44', '2026-07-28 17:50:44'),
(76, 'propuesta', 63, 'RAMOS GARCIA JOSMERY GISELA', 'ASISTENTE DE ESTIBA', 'Seria una propuesta si para el roro se puede hacer una delimitacion en piso con cal asi mejor visualización ya que ahora en temporada de vientos fuertes los conos se los lleva el viento', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-29 08:15:44', '2026-07-29 08:15:44'),
(77, 'propuesta', 27, 'CASTAÑEDA VALVERDE ELIZABETH ANGELICA', 'ASISTENTE DE ESTIBA', 'Buenas noches \r\nUna propuesta de mejora en las naves de contenedores \r\nCada vez que se habiliten alguna línea sea descarga o emb', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-29 08:37:06', '2026-07-29 08:37:06'),
(78, 'propuesta', 27, 'CASTAÑEDA VALVERDE ELIZABETH ANGELICA', 'ASISTENTE DE ESTIBA', 'Buenas noches \r\nUna propuesta de mejora en nave de contenedores \r\nCuando se habiliten alguna línea sea embarque o descarga  siempre se debe delimitar con un pin stension o cajas de piñas para evitar algún accidente ya que ahy ocasiones que no delimitan las líneas y hemos tenido que pedetear en medio de dos DSV sabemos que son robot y pueden fallar y de esa manera evitar accidentes.\r\nIgualmente para evitar demoras operativas y exista fluidez en las operaciones', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-29 08:45:57', '2026-07-29 08:45:57'),
(79, 'propuesta', 59, 'ANGULO RAMOS CARLOS GIORDANO', 'ASISTENTE DE ESTIBA', 'Buenos días ,recomiendo que en las operaciones de cemento sería mejor hacer los despachos en modalidad directo (barco a vehículo ) para eliminar el riesgo de un accidente a la hora de acercarse al vehículo a pedetiar y la ferificacion de la cantidad de big bag sería desde el pin station. \r\nNo digo que sea del barco al vehículo directo solo la modalidad (tipo de pedeteo ) donde nos permite pedetiar y generar ticket sin acercarnos al vehiculo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-29 10:42:58', '2026-07-29 10:42:58'),
(80, 'propuesta', 59, 'ANGULO RAMOS CARLOS GIORDANO', 'ASISTENTE DE ESTIBA', 'Buenos días , recomiendo que en operaciones del roro tengamos 4 personas a bordo dos que visualicen daños y dos que rotulen así en el punto de pedeteo ,poder tarjar y pedetar a la vez de forma rápida y verificada daños de una forma más rápida porque abordo ya se realizó la inspección de daños.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-29 10:46:05', '2026-07-29 10:46:05'),
(81, 'propuesta', 76, 'MELGAREJO AQUINO MILAGROS JUDITH', 'ASISTENTE DE ESTIBA', 'Buenas Tardes:\r\nPresento propuesta de mejora para el formato de compensación de horas, la cual tiene un texto mas acorde y neutra a las solicitudes o casuísticas, las cuales generan el debe de horas de trabajo,  adjunto en Word y PDF para su modificación adicional, si fuera necesario.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-29 18:48:28', '2026-07-29 18:48:28'),
(82, 'propuesta', 27, 'CASTAÑEDA VALVERDE ELIZABETH ANGELICA', 'ASISTENTE DE ESTIBA', 'Buenas tardes \r\nMejoras para nave RoRo\r\nEs muy necesario tener un señalero para la segregación de autos ya que es un elemento fundamental para una adecuado segregación.\r\nEs cierto que en las asignaturas ponen tallys para segregación y pedeteo,pero el Tally asignado a pedeteo no tiene la posibilidad de dejar su espacio para poder guiar,ya que algunos compañeros conductores desconocen el orden de BL.\r\nDe igual manera el señalero debe estar capacitado para la segregación, si es un compañero OPM debe tener el conocimiento de los BL ,también se podria asignar a un Tally solo para la segregación porque siempre pasa que algunos conductores dejan los autos en  donde no corresponde y generan retraso o desorden ya que después tenemos que mover las autos y eso podría ocasionar algún daño de la unidad.\r\nFinalmente el Tally de segregación ya tendría toda la información si existe algun auto de canal Rojo para que puede mapearlo y de esa manera exista un mejor orden y ubicación de vehículos.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-30 19:00:28', '2026-07-30 19:00:28'),
(83, 'solicitud', 17, 'MENA VALDERRAMA GIANELA MILAGROS', 'ASISTENTE DE ESTIBA', 'Poner más señaleros en RORO segregación donde hacen las tarjas, ya que ha pasado que los conductores ponen los autos en otras ubicaciones que no siguen los planos y eso ocasiona atrasos', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 02:56:41', '2026-07-31 02:56:41'),
(84, 'solicitud', 17, 'MENA VALDERRAMA GIANELA MILAGROS', 'ASISTENTE DE ESTIBA', 'He visto muchas veces que labor convoca poco personal en Roro más que todo tarja y por eso queda atrasado la tarja habiéndose concluido la nave siempre queda pendiente muchas tarjas por regularizar. Sería lo mejor que pongan asignación en Roro por ubicaciones ir ejemplo si hay en A6 y muelle 1 que pongan los tallys ya designados para cada ubicación y no haiga todo un desorden al momento de la operación sería tarja muelle 1 , tarja A6 de esa forma habría una mejor organización de trabajo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 03:21:05', '2026-07-31 03:21:05'),
(85, 'observacion', NULL, NULL, NULL, 'En el roro para las tarjas hay momentos donde no se puede hacer un buen relevo porque ponte tu terminaste de tarjar un lado y te mueves a otro pero en el transcurso ya no viste si pusieron otros o no y tu relevas qué ya esta listo podríamos implementar algún otro tipo de método para ese tema', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 03:52:07', '2026-07-31 03:52:07');
INSERT INTO `sugerencias_tallyman` (`id`, `canal`, `colaborador_id`, `colaborador_nombre`, `colaborador_cargo`, `detalle`, `puntaje`, `puntaje_comentario`, `puntaje_por`, `puntaje_at`, `respuesta_whatsapp`, `respuesta_whatsapp_por`, `respuesta_whatsapp_at`, `respuesta_whatsapp_message_id`, `created_at`, `updated_at`) VALUES
(86, 'observacion', NULL, NULL, NULL, 'En estos últimos dos meses veo irregularidades con el coordinador de aforo Jhonatan , un día en turno como vio que éramos 5 Tallyman para desconsolidado de autos , se expresó de una manera inapropiada para nosotros , diciendo porque mandan tanta gente ahora de seguro va ver errores y eso que todavía ni comenzaba el trabajo . Donde le respondí que eso no iba a pasar ya que mi equipo estaba capacitado y no hubo errores ese día a pesar de que tuvimos un aprox de 170 vehículos. El día de hoy hubo otra caso con la ubicación en minerales teníamos 4 clientes , la empresa JINGOLD en sus tickets de balanza figuraba la ubicación BR5C y las otras 3 aparecía con la ubicación BR5B . Entonces mis compañeras de patio pedeteaban con la ubicación que salía en ticket. Hasta que después de 20 camiones el coordinador de aforo decide querer reportarlas por la mala ubicación que la compañera había realizado en su pedeteo para darle salida a la unidad . Donde ellas no tienen la culpa porque se basan a la ubicacion que sale en el ticket ya que contaba con 3 clientes que descargan en diferentes zonas . Ademas el coordinador de aforo manda la ruta asignada a cada unidad y va de la mano con el analista que tuvo que detectar ese error de ubicación. Para finalizar como detecte el error ellos ya no pudieron amonestar a las compañeras ya que la culpa de ellos.\r\nESTO NOS QUEDA CLARO QUE NO AFRONTAN SUS ERRORES Y QUE LA RESPONSABILIDAD CAE HACIA EL TALLY , SI ES QUE EL TALLY NO REFUTA O NO SABE LOS PROCESOS DE CADA ÁREA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 04:28:41', '2026-07-31 04:28:41'),
(88, 'consulta', 67, 'VASQUEZ MORA SHAUNNY MILAGROS', 'ASISTENTE DE ESTIBA', 'Buenas noches, quisiera saber si en el área de aforo. La ruta (ubicación) que se le brindan a la unidad de mineral sale por defecto o es que en el encargado del dia lo asigna?, ¿ La ubicación que fuese asignada a la unidad siempre va ser BR5B o es que tambien puede ser a BR5C entre otra?.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 04:31:12', '2026-07-31 04:31:12'),
(89, 'propuesta', 65, 'TORRES RICHARTE JOSE EDUARDO', 'ASISTENTE DE ESTIBA', 'En el patio de minerales sería bueno colocar 2 letreros grandes diciendo PARCIALES Y ENTEROS ya que así el conductor no se mete en el Carril que no le corresponde y no obstaculiza , haciendo que halla un mejor flujo y las carretas no se queden esperando más de 2 horas.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 04:32:30', '2026-07-31 04:32:30'),
(90, 'propuesta', 67, 'VASQUEZ MORA SHAUNNY MILAGROS', 'ASISTENTE DE ESTIBA', 'Para patio de contenedores, en estas ultimas semanas estuve observado que hay picos de fluencia de carretas para recepción y retiro de contenedores lo cual aún los conductores no tienen claro la ruta hacia la llegada a su ubicación que bloque se encuentra el contenedor a despachar o ingresar. Por consecuencia es que se tardan en llegar al punto designado y demoran al salir. Consideró que se puede implementar carteles con el mapa de los bloques del patio de contenedores diciendo \"USTED SE ENCUENTRA AQUI\" y hacerle llegar una difución a sus encargados transportista para que siempre al ingresar al puerto puedan guiarse de los carteles.', 7, '', 'TERRY PEREYRA EDGARD DAVID', '2026-07-31 19:29:31', NULL, NULL, NULL, NULL, '2026-07-31 04:49:36', '2026-07-31 19:29:31'),
(91, 'solicitud', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', 'Por favor me tengan en cuenta para hacer sombras en los puestos que aún no he estado, ya que un día me programaron en balanza de minerales y es la primera vez que estoy ahí, no tengo inconvenientes en ir a algún puesto , pero creo se debe considerar como en mi caso que recién bajo del gate y necesito actualización de cada punto.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 12:46:01', '2026-07-31 12:46:01'),
(92, 'propuesta', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', 'Por favor me tengan en cuenta para hacer sombras en los puestos que aún no he estado, ya que un día me programaron en balanza de minerales y es la primera vez que estoy ahí, no tengo inconvenientes en ir a algún puesto , pero creo se debe considerar como en mi caso que recién bajo del gate y necesito actualización de cada punto.', 2, '', 'TERRY PEREYRA EDGARD DAVID', '2026-07-31 19:22:04', NULL, NULL, NULL, NULL, '2026-07-31 12:46:10', '2026-07-31 19:22:04'),
(93, 'propuesta', 18, 'OCAÑA ALVINO KAREN SARAI', 'ASISTENTE DE ESTIBA', '-Para la zona de minerales, se necesita más apoyo para la señalización de los camiones , ya que cuando hay demasiada carga veo que no se abastec y eso genera el desorden y que las unidades ingresen por dónde quieran \r\n-Otro punto también es que los clientes a veces se mandan solos y dan ordenes de ingreso cuando aún nosotros no le damos la orden y eso genera problemas porque se pueden ir unidades sin pedetear.', 2, 'Reviasar', 'TERRY PEREYRA EDGARD DAVID', '2026-07-31 19:21:52', NULL, NULL, NULL, NULL, '2026-07-31 12:49:53', '2026-07-31 19:21:52'),
(94, 'observacion', NULL, NULL, NULL, 'En estos últimos días he notado el buen desempeño de la coordinadora Yadira, creo es la labor de una coordinadora, que debería de ser soporte para nosotros, no siempre ver lo malo y que solo se acerque para buscar errores, lo que he notado de alguna coordinadora es que solo llegan y se ponen a un lado a hacer preguntas y hablar cosas cuando uno está concentrado en hacer su trabajo y pedetear , lo que es incómodo porque nos puedes desconcentrar y equivocarnos y eso es muy asfixiante la verdad.\r\nCreo que deberian de darnos más apoyo creo yo en vez de solo buscar errores , ya que ni saben todos los procesos del trabajo y eso también debería saberlo, creo es lo fundamental.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 13:02:33', '2026-07-31 13:02:33'),
(95, 'propuesta', 47, 'LORA LEYVA NYLEEN MILENA', 'ASISTENTE DE ESTIBA', 'Tema de nave de rorro en segregación y ubicación de vehículos cuando no ay señalero,\r\nHay láser de día y de noche que sería solo marcar o indicar en que posición dejaría el vehículo si necesidad de un señalero la compañera de segregación solo le señalaría el lado donde deberían colocarse', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 22:46:59', '2026-07-31 22:46:59'),
(96, 'observacion', NULL, NULL, NULL, 'En Gate ahí una indicación de parantes para depósito pero siempre para apagado sería bueno que lo prendan de noche para indicar y conductores nuevos no se vayan por otro lado', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-31 22:48:11', '2026-07-31 22:48:11'),
(97, 'observacion', NULL, NULL, NULL, 'Asunto: Actualización de ubicaciones en el área de Minerales / Stuffing\r\n\r\nEstimado equipo,\r\nHago la siguiente observación con respecto a las ubicaciones asignadas en el área de Minerales:\r\n\r\nUbicación correcta: Se confirmó que toda asignación en el área de Minerales debe ser bajo la ubicación BR5B (en el ticket se registró por error BR5C).\r\n\r\nOjo: Previamente se utilizaban las ubicaciones BR5A, BR5B y BR5C, pero esta regla ha cambiado.\r\n\r\nAcción requerida:\r\nPor favor, asegúrense de notificar este cambio a todo el personal que baje del GATE CI para evitar errores operativos y mantener una información alineada con todos los compañeros de tallys.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-01 16:54:44', '2026-08-01 16:54:44'),
(98, 'propuesta', 54, 'PALOMINO PARDO ASHLEY JENNIFER', 'ASISTENTE DE ESTIBA', 'Asunto: Propuesta de descongestión operativa en la Zona de Minerales.\r\n\r\nEstimados,\r\nLes escribo para reportar una situación operativa en la zona de Minerales y presentar una propuesta de mejora:\r\n\r\n1. Diagnóstico de la situación\r\nActualmente, la zona no cuenta con el espacio físico suficiente para atender de 4 a 6 clientes de forma simultánea. Esta saturación genera los siguientes inconvenientes:\r\n\r\n-Obstrucción de vías: En el área de llenos y parciales, algunos conductores no respetan las filas y se estacionan detrás de otras unidades.\r\n\r\n-Riesgo operativo y congestión: Esto bloquea el carril principal de ingreso por donde transitan los vehículos de contenedores, los ITVs y el bus de personal.\r\n\r\n2. Propuesta de solución\r\nPara mantener la fluidez operativa y mitigar riesgos de tráfico:\r\n\r\n-Apertura de zona auxiliar: Solicito que, al detectar una carga de 4 o más clientes en simultáneo, se habilite una zona aparte o de contingencia.\r\n\r\n-Beneficio: Esto distribuirá el flujo de camiones, evitará el embotellamiento en un solo punto y garantizará el libre tránsito de las demás unidades.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-01 17:10:02', '2026-08-01 17:10:02'),
(99, 'solicitud', 54, 'PALOMINO PARDO ASHLEY JENNIFER', 'ASISTENTE DE ESTIBA', 'Solicitud de apoyo operativo - Personal Gate CI:\r\n\r\nEstimados, quería solicitar apoyo con el personal que baje del GATE CI. Ellos tienen más tiempo en esa área, sin estar en la zona de ZOP y no están al tanto de los procedimientos actuales en áreas críticas como Balanza 2 de Minerales, Desconsolidado y Minerales Stuffing.\r\n\r\nPido de favor que se les pueda brindar un acompañamiento inicial o un refrescamiento de procesos para evitar errores operativos, cuidar la fluidez del trabajo y apoyarlos en su adaptación. ¡Muchas gracias!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-01 17:19:32', '2026-08-01 17:19:32'),
(100, 'propuesta', 54, 'PALOMINO PARDO ASHLEY JENNIFER', 'ASISTENTE DE ESTIBA', 'Asunto: Coordinación previa de segregación de carga general por turno.\r\n\r\nEstimados,\r\nPor medio de la presente, solicito que al inicio de cada turno de descarga de naves de carga general (como en el caso de la nave Chang an Cheng), el supervisor a cargo brinde las indicaciones precisas sobre la clasificación de la carga antes de iniciar las maniobras.\r\n\r\nPuntos clave a coordinar antes del inicio del turno:\r\n\r\n-Identificación previa: Especificar la diferenciación de la carga (sea bolas de acero, barras de acero, bultos, etc.) según códigos, colores o medidas.\r\n\r\n-Asignación de espacios: Definir con claridad las zonas destinadas para cada tipo de carga en el área de acopio antes de mover el material.\r\n\r\nObjetivo:\r\nEvitar la mezcla de la carga en zonas ya ocupadas o erróneas, eliminando la necesidad de reordenar la carga anterior, lo cual genera pérdida de tiempo y resta fluidez a la operación de descarga.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-01 17:39:33', '2026-08-01 17:39:33'),
(101, 'observacion', NULL, NULL, NULL, 'Fue un caso durante la descarga en la nave Chang an Cheng, se identificó que la carga dejada por el turno dia saliente se encontraba mezclada la carga, sin clasificación por códigos ni por medidas. Esto representaba un riesgo de demoras en la descarga del turno entrante.\r\n\r\nRealizamos una acción correctiva.\r\nBajo las indicaciones del supervisor de turno, el equipo procedió al ordenamiento, segregación y acomodo de la carga, clasificándola estrictamente por código y medida para asegurar un despacho correcto y ágil de las unidades.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-01 17:48:50', '2026-08-01 17:48:50'),
(102, 'observacion', NULL, NULL, NULL, 'Tengo una duda y/o sugerencia o inquietud en el tema de stuffing de minerales debido a cual es el programa que se esta utilizando para dicho proceso (excel o sistema implementado)? ya que en mi turno no pude encontrar información de los contenedores a cerrar o que han sido precintados en mi turno ,ya que había información incompleta en el sistema . Luego después de hacer averiguaciones me indican que el turno anterior han trabajado en el excel. Creo yo que debería haber un proceso único ya que al hacer en ambos programas se pierde o se tiene información incompleta .', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-02 02:12:37', '2026-08-02 02:12:37'),
(103, 'observacion', NULL, NULL, NULL, 'Tengo una duda y/o sugerencia o inquietud en el tema de stuffing de minerales debido a cual es el programa que se esta utilizando para dicho proceso (excel o sistema implementado)? ya que en mi turno no pude encontrar información de los contenedores a cerrar o que han sido precintados en mi turno ,ya que había información incompleta en el sistema . Luego después de hacer averiguaciones me indican que el turno anterior han trabajado en el excel. Creo yo que debería haber un proceso único ya que al hacer en ambos programas se pierde o se tiene información incompleta .', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-02 02:13:04', '2026-08-02 02:13:04'),
(104, 'propuesta', 74, 'MARTINEZ RAMOS RONALD MARCELO', 'ASISTENTE DE ESTIBA', 'Buen dia soy Ronald y si el dia de hoy hago mi propuesta es para poder implementar en el ingreso de las unidades de minerales. Para que no se aglomeren en en el Patio (BR5B) sería bueno implementar un señalero que pueda tener el control de dichas unidades y su parqueo sería detrás de la balanza 2 , e ir enviando de acuerdo al requerimiento del tally en coordinación con el coordinador de aforo y despachador .Ya que en mi turno lo hemos aplicado y a funcionado de la mejor manera.', 8, '', 'TERRY PEREYRA EDGARD DAVID', '2026-08-04 00:10:22', 'Gracias Ronald propuesta recibida', 'TERRY PEREYRA EDGARD DAVID', '2026-08-04 00:10:41', '3EB056B6AF78CEE791C735', '2026-08-03 14:45:14', '2026-08-04 00:10:41'),
(105, 'propuesta', 31, 'NARIO HERRERA EDGAR JORGE', 'ASISTENTE DE ESTIBA', 'Hola.\r\nEn el último roro se contó con el personal suficiente para tarjas y pedeteos al inicio operativo, la idea principal es poder avanzar con ambas cosas a la par, pero no se pudo, a mi parecer por un error de coordinación; dejando más tarjas pendientes, lo que sugeriría es poder asignar el orden en conjunto de Tallys de tarjas y Tallys de pedeteos, por ejemplo 2 de tarjas y 2 de pedeteos POR LÍNEA o por PUNTO DE PEDETEO, en caso no haya mucho personal 1 y 3, que puedan rotar durante el turno sea cual sea el horario de inicio, pero ambos subgrupos cumpliendo la misma hora de funciones en cada punto, además suponiendo que el orden de BL’s, marcas o prioridades de vehículos y bultos por deck sean variados en la segregación, enviar a estos grupos a BT1, M2A1 o AR1A dependiendo el orden de descarga, así podrían asegurar que en cada punto están siendo segregados los vehículos correspondientes. Estos equipos se harían cargo de sus filas de segregación y validación de rótulos en cuanto a códigos para posteriormente no haya inconvenientes en los despachos.\r\nFinalmente la rotación de funciones permitirá a cada tally tener aproximadamente la misma cantidad de pedeteos y tarjas hechas.', NULL, NULL, NULL, NULL, 'Gracias por tu propuesta', 'TERRY PEREYRA EDGARD DAVID', '2026-08-03 22:17:39', '3EB036D99B0E725AC7CF64', '2026-08-03 16:40:15', '2026-08-03 22:17:39'),
(109, 'observacion', NULL, NULL, NULL, 'Para los seleccionados como Tallys Sombra de Coordinador, recomiendo tener claro el procedimiento de lo que han de realizar, porque en mi turno solo veia al compañero como casi 5 horas en vestuarios durmiendo lo cual genera incomodidad con su celular deberian tener mayor criterio al seleccionar todos conocemos los procesos en patio solo son muy pocos los que requieren apoyo., el soporte mayormente lo hacemos directo con el planning en turno, el unico soporte con el coordinador tallyman es para informar el tema de relevo o para casos especificos cuando incurrimos error con el pedeteo o casos casuísticos errores de citas o citas vencidas o mal registro de citas que influyan con el pedeteo ahi si pedimos apoyo al coordinador, o temas de materiales , adicionales a ellos para habilitacion de tareas nuestro apoyo directo es con el dispatcher en turno o correcciones que no requieran intervencion como imagenes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04 01:01:01', '2026-08-04 01:01:01'),
(112, 'observacion', NULL, NULL, NULL, 'Quisera saber cómo va a ser respecto a las horas de rancho, ya que hay ocasiones que algunas compañeras se demoran 1 hora y media en cenar y han llegado tranquilamente al puesto y eso no me parece justo , porque por el tema de cena algunos se han ganado declaraciones por eso y no me parece justo que para unos si haya declaraciones y para otros no , en todo caso debe ser igual para todos, de la misma manera para rancho frío, que algunos se toman más de la media hora o la hora completa que se le da la coordinadora y no se les dice nada, ahí creo que sí no se puede organizar no debería de ver rancho frío para nadie, para evitar eso y evitar también que la coordinadora haga una mala distribución y algunos salgan más o menos tiempo , sin rancho frío para nadie.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04 02:09:49', '2026-08-04 02:09:49'),
(113, 'observacion', NULL, NULL, NULL, 'Respecto a los apoyos tallys a las coordinadoras , no sé si ahora se van a deslingar de las declaraciones o las observaciones que tiene un tally, ya que Yanira por ejemplo , se ha tomado el trabajo de reportar y mandar a declarar a un tally , y que ya se aclaro hoy que no debería de hacerlo , pero lo está haciendo porque no es ni una o 2 veces que lo hace, se está tomando cargos que corresponde a la coordinadora, ahora otro tema es que llegó tarde a una charla pre operativa cuando la coordinadora Jenifer ya había empezado la charla y no se si se le reporto tardanza, creo a todos los tallys se le da el tema de declaración cuando sucede eso , entonces no sé si ellos van a tener ciertos privilegios o van a dejar de ser tallys para ser solo apoyo, quisiera que se aclare ese tema en una reunión, porque se debería de ser justo e igual para todos.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04 02:18:22', '2026-08-04 02:18:22');
